import{_ as o,o as c,c as d,a5 as l}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"then方法总结 1","description":"创建一个新的 P ，然后返回它； 然后在 P 的构造函数中，我们执行以下逻辑； 实现透传 当 P 的状态凝固时，我们立即调用成功回调和失败回调； 当 P 的状态为 pending 时，我们将成功回调和失败回调放入回调函数数组中。 我们调用以及放入回调数组的成功和失败回调是经过包装。","frontmatter":{"title":"then方法总结 1","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","异步编程"],"description":"创建一个新的 P ，然后返回它； 然后在 P 的构造函数中，我们执行以下逻辑； 实现透传 当 P 的状态凝固时，我们立即调用成功回调和失败回调； 当 P 的状态为 pending 时，我们将成功回调和失败回调放入回调函数数组中。 我们调用以及放入回调数组的成功和失败回调是经过包装。","sidebarWeight":80,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/11-异步编程/promise实现/then方法总结 1.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/05-异步编程/promise实现/then方法总结 1.md","filePath":"posts/JavaScript系统教程/05-异步编程/promise实现/then方法总结 1.md"}'),t={name:"posts/JavaScript系统教程/05-异步编程/promise实现/then方法总结 1.md"};function i(n,e,r,a,s,h){return c(),d("div",null,[...e[0]||(e[0]=[l('<div><h1 id="then方法总结-1" tabindex="-1">then方法总结 1 <a class="header-anchor" href="#then方法总结-1" aria-label="Permalink to &quot;then方法总结 1&quot;">​</a></h1><blockquote><p>本节目标：理解“then方法总结 1”的核心思路，并能把它用于实际开发或面试表达。 创建一个新的<code>P</code>，然后返回它； 然后在<code>P</code>的构造函数中，我们执行以下逻辑；</p></blockquote><ul><li>实现透传</li><li>当<code>P</code>的状态凝固时，我们立即调用成功回调和失败回调；</li><li>当<code>P</code>的状态为<code>pending</code>时，我们将成功回调和失败回调放入回调函数数组中。</li></ul><p>我们调用以及放入回调数组的成功和失败回调是经过包装过的，它做了以下处理：</p><ul><li>对回调函数调用的代码进行<code>Try catch</code>包装，以对回调函数执行时内部抛出的错误进行捕捉；比如<code>finally</code>的实现中，<code>Promise.resolve(fn())</code>，<code>fn()</code>内部抛出了一个错误；</li><li>对成功回调函数和失败回调函数的返回值进行判断，是否是一个<code>promise</code>对象； <ul><li>如果是<code>promise</code>对象，则添加回调，并将状态值传递出来；</li><li>如果不是，就直接<code>resolve</code>这个回调函数的返回值；</li></ul></li></ul><p>使用<code>then</code>方法意味着：</p><ul><li>给之前的期约添加回调函数；</li><li><code>then</code>方法的两个参数即成功回调和失败回调，需要它之前的期约状态凝固时才会调用；</li><li><code>then</code>方法会返回一个<code>promise</code>，因此可以链式调用，即<code>then().then</code>来添加回调函数；</li><li><code>then</code>方法是执行成功还是失败回调，取决于它所订阅期约的状态；</li></ul><p>then回调函数的执行逻辑 执行成功回调时：</p><ul><li>先看这个回调执行会不会报错，如果会报错，<code>then</code>所创建期约会<code>reject</code>，后续<code>then</code>的失败回调会执行；</li><li>如果没有报错，我们取回调函数的执行结果，然后进行判断： <ul><li>如果不是期约，直接<code>resolve</code>这个执行结果；</li><li>如果是期约，我们给这个期约添加回调函数，并且等待它的状态凝固； <ul><li>如果这个期约状态凝固为成功，<code>then</code>所创建的期约会<code>resolve</code>这个期约的成功值，，后续<code>then</code>的成功回调会执行；</li><li>如果这个期约状态凝固为失败，<code>then</code>所创建的期约会<code>reject</code>这个期约的失败原因，，后续<code>then</code>的失败回调会执行；</li></ul></li></ul></li></ul><p>执行失败回调时：</p><ul><li>如果没有定义失败回调，默认的失败回调为：<code>err</code> <code>=\\&gt;</code> <code>{</code> <code>throw</code> <code>err</code> <code>}</code>，即抛出错误；</li><li>先看这个回调执行会不会报错，如果会报错，<code>then</code>所创建期约会<code>reject</code>，后续<code>then</code>的失败回调会执行；</li><li>如果没有报错，我们取回调函数的执行结果，然后进行判断： <ul><li>如果不是期约，直接<code>resolve</code>这个执行结果；</li><li>如果是期约，我们给这个期约添加回调函数，并且等待它的状态凝固； <ul><li>如果这个期约状态凝固为成功，<code>then</code>所创建的期约会<code>resolve</code>这个期约的成功值，，后续<code>then</code>的成功回调会执行；</li><li>如果这个期约状态凝固为失败，<code>then</code>所创建的期约会<code>reject</code>这个期约的失败原因，，后续<code>then</code>的失败回调会执行；</li></ul></li></ul></li></ul><p>简言之，<code>then</code>在执行回调函数时，会检查回调函数的返回值，如果是期约，则等待它的状态凝固；并且在它所等待的期约状态成功时，将自身创建并要返回的期约状态改为成功，<code>relove</code>它所等待的期约的成功值；在它所等待的期约状态失败时，将自身创建并要返回的期约状态改为失败，<code>reject</code>它所等待的期约的失败原因；</p><p>由此可知，<code>finally,catch</code>等后面通过<code>then</code>添加的回调函数，都要<code>finally</code>和<code>catch</code>中定义的<code>promise</code>状态凝固才会执行；</p><ul><li>不管如何，要<code>then()</code>后面的<code>then</code>中的回调执行；我们要先将当前<code>then</code>的成功或失败回调执行完才行；有可能是立即执行的回调（订阅了一个状态立即凝固的<code>promise</code>），也有可能是异步执行的回调（订阅了一个状态为<code>pending</code>的<code>promise</code>）；</li><li>在执行<code>then</code>的成功或失败回调时，如果执行结果是一</li></ul></div>',1)])])}const _=o(t,[["render",i]]);export{u as __pageData,_ as default};
